import './App.css';
import Gallery from './components/Gallery';
import React, {useState, useEffect} from 'react'
import { useDataLayerValue } from './DataLayer'
import * as Realm from "realm-web";
import { data } from 'autoprefixer';
const appId = "keenan-kgkzv"; // e.g. myapp-abcde
const appConfig = {
  id: appId,
  timeout: 10000,
};

function App() {

  const [loading, setLoading] = useState(false);
  const [{data, page},dispatch] = useDataLayerValue();



  useEffect( async() => {
    async function connectDB() {
     const app = new Realm.App(appConfig);
     const credentials = Realm.Credentials.serverApiKey("9icRBkm9bOSqAG9dqw7xsOmUSgZom07esC78XDIdSm4Gl9u3BXdJK93hRqOIeWgT");
     const user = await app.logIn(credentials);
     const mongodb = app.currentUser.mongoClient("mongodb-atlas");
     const artwork = mongodb.db("keenan").collection("artwork");
     const data = await artwork.find({});
     console.log("one");
     console.log(data[0].catolog);
     dispatch({
      type: "SET_DATA",
      data: data[0].catolog,
    });
    setLoading(true)
    console.log("two");
    console.log(data[0].catolog);
  }
  connectDB();
  }, [])

  const profilePage = () => {
    dispatch({
      type: "SET_PAGE",
      page: "profile",
    });
  }

  const mainPage = () => {
    dispatch({
      type: "SET_PAGE",
      page: "main",
    });
  }

  const contentPage = () => {
    dispatch({
      type: "SET_PAGE",
      page: "content",
    });
  }

  const project = (type) => {
    switch(type) {

      case "main":   return <h1>main</h1>;
      case "profile":   return <h1>profile</h1>;
      case "content": return <h1>content</h1>;

      default:      return <h1>No project match</h1>
    }
  }

  return (
    project(page)
  );
}

export default App;
